import{c as i,ah as a,L as e,O as l}from"./chunks/framework.YKVbmyBD.js";const k=JSON.parse('{"title":"进程管理","description":"","frontmatter":{},"headers":[],"relativePath":"web-src/fovlin-notes/linux-guide/use-cli/proc.md","filePath":"web-src/fovlin-notes/linux-guide/use-cli/proc.md"}'),p={name:"web-src/fovlin-notes/linux-guide/use-cli/proc.md"};function n(t,s,h,d,o,c){return a(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="进程管理" tabindex="-1">进程管理 <a class="header-anchor" href="#进程管理" aria-label="Permalink to “进程管理”">​</a></h1><p>在命令行中查看并管理进程。</p><h2 id="查看-pid" tabindex="-1">查看 PID <a class="header-anchor" href="#查看-pid" aria-label="Permalink to “查看 PID”">​</a></h2><p>查看 PID 的方法有多种，包括通过适用基础的 <code>ps</code> 命令，或使用可视化的 top 系列命令，而 Linux 更多倾向于使用后者。</p><h3 id="ps-命令" tabindex="-1">ps 命令 <a class="header-anchor" href="#ps-命令" aria-label="Permalink to “ps 命令”">​</a></h3><p>Linux 的每个进程都会创建一个 PID，作为该进程的唯一标识，<code>ps -He</code> 可以查看所有的进程 PID 的树状结构，可以通过 <code>|</code> 管道传入 <code>grep</code> 命令对输出结果进行筛选。</p><p>查询包含 <code>code</code> 字符串的进程：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code</span></span></code></pre></div><blockquote><p><code>-i</code> 表示忽略 grep 查询对大小的限制筛选。</p></blockquote><p>例如产生以下输出：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>   3289 ?        00:00:37     code</span></span>
<span class="line"><span>   3292 ?        00:00:00       code</span></span>
<span class="line"><span>   3337 ?        00:00:59         code</span></span>
<span class="line"><span>   3293 ?        00:00:00       code</span></span>
<span class="line"><span>   3295 ?        00:00:00         code</span></span>
<span class="line"><span>   3379 ?        00:03:21           code</span></span>
<span class="line"><span>   3339 ?        00:00:01       code</span></span>
<span class="line"><span>   3412 ?        00:00:06       code</span></span>
<span class="line"><span>   3498 ?        00:00:02       code</span></span>
<span class="line"><span>   3511 ?        00:00:27       code</span></span>
<span class="line"><span>   3608 ?        00:00:00         code</span></span>
<span class="line"><span>   3627 ?        00:00:06         code</span></span></code></pre></div><p>后续若要对进程进行操作，仅需操作根进程的 PID 即可，即 <code>3289</code>。</p><p>更多用法查看 PID 适用 <code>ps</code> 命令，使用 <code>man ps</code> 或 <code>ps --help</code> 命令获得帮助。</p><h3 id="top-系列命令" tabindex="-1">top 系列命令 <a class="header-anchor" href="#top-系列命令" aria-label="Permalink to “top 系列命令”">​</a></h3><p>目前有几款不同的 top，包括 <code>top</code> <code>htop</code> <code>btop</code> <code>atop</code> 等，其中 <code>htop</code> 以高实用性受欢迎，<code>btop</code> 颜值最高，但对终端窗口大小有限制，过小的窗口无法启动，此处以 <code>htop</code> 作为示例，<code>top</code> 之外的 top 系列命令在绝大多数发行版中需要手动安装。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">htop</span></span></code></pre></div><p>终端输入 <code>htop</code> 后将会显示所有的 PID 与各类资源占用情况，同时可以使用键盘交互式地查找或操作一些进程。</p><h2 id="查看资源占用" tabindex="-1">查看资源占用 <a class="header-anchor" href="#查看资源占用" aria-label="Permalink to “查看资源占用”">​</a></h2><p>使用 top 系列命令可以查询系统常用资源的占用，也是最常见的方法之一，但针对特定资源，有特定的命令进行查询。</p><h3 id="常用资源占用" tabindex="-1">常用资源占用 <a class="header-anchor" href="#常用资源占用" aria-label="Permalink to “常用资源占用”">​</a></h3><p><code>htop</code> 或其他系列命令将显示常用资源的占用情况，包括 CPU 占用，内存占用，线程数，PID 信息等。</p><h3 id="内存占用" tabindex="-1">内存占用 <a class="header-anchor" href="#内存占用" aria-label="Permalink to “内存占用”">​</a></h3><p><code>free</code> 命令查看运行内存占用情况，常用以下命令进行查看：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">free</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span></code></pre></div><p><code>-h</code> 将忽略具体大小，以 MB 或 GB 单位进行显示。</p><h3 id="查看流量进出速度" tabindex="-1">查看流量进出速度 <a class="header-anchor" href="#查看流量进出速度" aria-label="Permalink to “查看流量进出速度”">​</a></h3><p>使用 <code>nload</code> 命令可以查看流量进出速度，进出速度将显示分为两个列表显示。</p><h3 id="查看端口占用情况" tabindex="-1">查看端口占用情况 <a class="header-anchor" href="#查看端口占用情况" aria-label="Permalink to “查看端口占用情况”">​</a></h3><p><code>netstat</code> 包含在 <code>net-tools</code> 软件包中，默认不会安装在绝大多数发行版中，需要手动安装。</p><p>常用参数如下</p><p>使用 <code>-tunlp</code> 参数列出所有监听协议端口占用情况，通过管道传入 <code>grep</code> 进行过滤以达到查询端口被哪个进程占用的效果。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tunlp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span></span></code></pre></div><h2 id="结束进程" tabindex="-1">结束进程 <a class="header-anchor" href="#结束进程" aria-label="Permalink to “结束进程”">​</a></h2><p>常用的结束进程的方法有使用 <code>kill</code> 匹配进程 PID 进行结束，或使用 <code>pkill</code> 匹配进程名进行结束。</p><h3 id="kill-命令" tabindex="-1">kill 命令 <a class="header-anchor" href="#kill-命令" aria-label="Permalink to “kill 命令”">​</a></h3><p>使用 <code>kill [-n] PID</code> 以杀掉命令，其中 <code>n</code> 表示要发送的数字信号，常用信号如下</p><ul><li><p>SIGKILL（信号9）：立即结束进程，不能被捕获或忽略。</p></li><li><p>SIGTERM（信号15）：正常结束进程，可以被捕获或忽略。</p></li><li><p>SIGSTOP（信号19）：暂停进程，不能被捕获、忽略或结束。</p></li><li><p>SIGCONT（信号18）：继续执行被暂停的进程。</p></li><li><p>SIGINT（信号2）：通常是Ctrl+C产生的信号，可以被进程捕获或忽略。</p></li></ul><p>例如查询到 code 进程 PID 为 3389，现在要杀掉该进程，使用如下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3389</span></span></code></pre></div><p>或指定信号，强制结束：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3389</span></span></code></pre></div><h3 id="pkill-命令" tabindex="-1">pkill 命令 <a class="header-anchor" href="#pkill-命令" aria-label="Permalink to “pkill 命令”">​</a></h3><p>pkill 命令可以匹配进程名来杀掉进程，例如杀掉进程名为 <code>code</code> 的命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code</span></span></code></pre></div><p>有时进程名过长，可以使用 <code>-f</code> 选项杀掉所有包含某个字符串的进程名的进程，例如杀掉 <code>prismlauncher</code> 进程可以使用如下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prism</span></span></code></pre></div>`,46)])])}const g=i(p,[["render",n]]);export{k as __pageData,g as default};
